import{_ as l,a as d}from"./chunks/rover_simulation.DsIwQfA8.js";import{_ as m}from"./chunks/hiwonder_ackermann.bMhWmXdo.js";import{_ as c}from"./chunks/hiwonder_tracked.D3OO8uS_.js";import{_ as h}from"./chunks/hiwonder_mecanum.CiOwITfD.js";import{_ as f,C as o,o as p,c as u,j as n,a,E as r,al as i}from"./chunks/framework.7vp1BMOE.js";const R=JSON.parse('{"title":"Марсохід","description":"","frontmatter":{},"headers":[],"relativePath":"uk/frames_rover/index.md","filePath":"uk/frames_rover/index.md"}'),v={name:"uk/frames_rover/index.md"};function _(g,e,b,k,w,y){const s=o("LinkedBadge"),t=o("Badge");return p(),u("div",null,[e[0]||(e[0]=n("h1",{id:"марсохід",tabindex:"-1"},[a("Марсохід "),n("a",{class:"header-anchor",href:"#марсохід","aria-label":'Permalink to "Марсохід"'},"​")],-1)),r(s,{type:"warning",text:"Experimental",url:"../airframes/#experimental-vehicles"}),e[1]||(e[1]=i('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Support for rover is <a href="./../airframes/#experimental-vehicles">experimental</a>. Maintainer volunteers, <a href="./../contribute/">contribution</a> of new features, new frame configurations, or other improvements would all be very welcome!</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Rover is not in the default PX4 firmware downloaded from QGC. Unlike for other vehicle types you will need to install it as custom firmware. For more information see <a href="./../config_rover/#flashing-the-rover-build">Flashing the Rover Build</a>.</p></div><p><img src="'+l+'" alt="Rovers"></p><p>PX4 provides support for the three most common types of rovers:</p><table tabindex="0"><thead><tr><th>Rover Type</th><th>Steering</th></tr></thead><tbody><tr><td><a href="#ackermann"><strong>Ackermann</strong></a></td><td>Direction is controlled by pointing wheels in the direction of travel. This kind of steering is used on most commercial vehicles, including cars, trucks etc.</td></tr><tr><td><a href="#differential"><strong>Differential</strong></a></td><td>Direction is controlled by moving the left- and right-side wheels at different speeds.</td></tr><tr><td><a href="#mecanum"><strong>Mecanum</strong></a></td><td>Direction is controlled by moving each mecanum wheel individually at different speeds and in different directions.</td></tr></tbody></table><p>The supported frames can be seen in <a href="./../airframes/airframe_reference#rover">Airframes Reference &gt; Rover</a>.</p><h2 id="ackermann" tabindex="-1">Ackermann <a class="header-anchor" href="#ackermann" aria-label="Permalink to &quot;Ackermann&quot;">​</a></h2>',7)),r(t,{type:"tip",text:"PX4 v1.16"}),e[2]||(e[2]=a()),r(t,{type:"warning",text:"Experimental"}),e[3]||(e[3]=i('<p>An Ackermann rover controls its direction by pointing the front wheels in the direction of travel — the <a href="https://en.wikipedia.org/wiki/Ackermann_steering_geometry" target="_blank" rel="noreferrer">Ackermann steering geometry</a> compensates for the fact that wheels on the inside and outside of the turn move at different rates. This kind of steering is used on most commercial vehicles, including cars, trucks etc.</p><p><img src="'+m+'" alt="Ackermann rover"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PX4 does not require that the vehicle uses the Ackermann geometry and will work with any front-steering rover.</p></div><h2 id="differential" tabindex="-1">Differential <a class="header-anchor" href="#differential" aria-label="Permalink to &quot;Differential&quot;">​</a></h2>',4)),r(t,{type:"tip",text:"PX4 v1.16"}),e[4]||(e[4]=a()),r(t,{type:"warning",text:"Experimental"}),e[5]||(e[5]=i('<p>A differential rover&#39;s motion is controlled using a differential drive mechanism, where the left and right wheel speeds are adjusted independently to achieve the desired forward speed and yaw rate. Forward motion is achieved by driving both wheels at the same speed in the same direction. Rotation is achieved by driving the wheels at different speeds in opposite directions, allowing the rover to turn on the spot.</p><p><img src="'+c+'" alt="Tracked Rover"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The differential setup also work for rovers with skid or tank steering.</p></div><h2 id="mecanum" tabindex="-1">Mecanum <a class="header-anchor" href="#mecanum" aria-label="Permalink to &quot;Mecanum&quot;">​</a></h2>',4)),r(t,{type:"tip",text:"PX4 v1.16"}),e[6]||(e[6]=a()),r(t,{type:"warning",text:"Experimental"}),e[7]||(e[7]=i('<p>A Mecanum rover is a type of mobile robot that uses Mecanum wheels to achieve omnidirectional movement. These wheels are unique because they have rollers mounted at a 45-degree angle around their circumference, allowing the rover to move not only forward and backward but also side-to-side and diagonally without needing to rotate first. Each wheel is driven by its own motor, and by controlling the speed and direction of each motor, the rover can move in any direction or spin in place.</p><p><img src="'+h+'" alt="Mecanum rover"></p><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="./../flight_modes_rover/">Drive Modes</a></li><li><a href="./../config_rover/">Configuration/Tuning</a></li><li><a href="./../flight_modes_rover/api">Apps &amp; API</a></li><li><a href="./../complete_vehicles_rover/">Complete Vehicles</a></li></ul><h2 id="симуляція" tabindex="-1">Симуляція <a class="header-anchor" href="#симуляція" aria-label="Permalink to &quot;Симуляція&quot;">​</a></h2><p>PX4 provides synthetic simulation models for <a href="./../sim_gazebo_gz/">Gazebo</a> of all three rover types to test the software and validate changes and new features:</p><ul><li><a href="./../sim_gazebo_gz/vehicles#ackermann-rover">Ackermann rover</a></li><li><a href="./../sim_gazebo_gz/vehicles#differential-rover">Differential rover</a></li><li><a href="./../sim_gazebo_gz/vehicles#mecanum-rover">Mecanum rover</a></li></ul><p><img src="'+d+'" alt="Rover gazebo simulation"></p>',8))])}const C=f(v,[["render",_]]);export{R as __pageData,C as default};
